def maxCandies(piles, k):
    if sum(piles) < k:
        return 0
    lo, hi = 1, max(piles)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        kids = 0
        for x in piles:
            kids += x // mid
        if kids >= k:
            lo = mid
        else:
            hi = mid - 1
    return lo
